final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: IoT Core device onboarding with Lambda-created thing-scoped policy

Resources:
  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: IotOnboardingLambdaPolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:DeletePolicy
                  - iot:AttachPolicy
                  - iot:DetachPolicy
                  - iot:AttachThingPrincipal
                  - iot:DetachThingPrincipal
                  - iot:CreateThing
                  - iot:DeleteThing
                  - iot:CreateThingGroup
                  - iot:DeleteThingGroup
                  - iot:AddThingToThingGroup
                  - iot:RemoveThingFromThingGroup
                Resource: '*'
              - Effect: Allow
                Action:
                  - logs:CreateLogGroup
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource: !Sub arn:aws:logs:${AWS::Region}:${AWS::AccountId}:log-group:/aws/lambda/*

  OnboardingLambda:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: !Sub iot-device-onboarding-${AWS::StackName}
      Runtime: nodejs22.x
      Handler: index.handler
      Timeout: 60
      Role: !GetAtt LambdaExecutionRole.Arn
      Code:
        ZipFile: |
          const {
            IoTClient, CreateThingCommand, DeleteThingCommand,
            CreatePolicyCommand, DeletePolicyCommand,
            AttachPolicyCommand, DetachPolicyCommand,
            CreateThingGroupCommand, DeleteThingGroupCommand,
            AddThingToThingGroupCommand, RemoveThingFromThingGroupCommand
          } = require('@aws-sdk/client-iot');
          const iot = new IoTClient();
          const response = require('cfn-response');

          const policyDoc = (region, accountId, thingName) => ({
            Version: '2012-10-17',
            Statement: [
              {
                Effect: 'Allow',
                Action: 'iot:Connect',
                Resource: `arn:aws:iot:${region}:${accountId}:client/${thingName}`
              },
              {
                Effect: 'Allow',
                Action: ['iot:Publish', 'iot:Receive'],
                Resource: `arn:aws:iot:${region}:${accountId}:topic/${thingName}/*`
              },
              {
                Effect: 'Allow',
                Action: 'iot:Subscribe',
                Resource: `arn:aws:iot:${region}:${accountId}:topicfilter/${thingName}/*`
              }
            ]
          });

          const notFound = (err) => err.name === 'ResourceNotFoundException';
          const conflict = (err) => err.name === 'ResourceConflictException';

          exports.handler = async (event, context) => {
            let status = 'SUCCESS';
            let responseData = {};
            let physicalId = event.PhysicalResourceId;

            try {
              const thingName = event.ResourceProperties.ThingName;
              const policyName = event.ResourceProperties.PolicyName;
              const thingGroupName = `${thingName}-group`;

              const accountId = context.invokedFunctionArn.split(':')[4];
              const region = context.invokedFunctionArn.split(':')[3];

              if (event.RequestType === 'Create' || event.RequestType === 'Update') {
                await iot.send(new CreateThingCommand({ thingName }));
                physicalId = thingName;

                let thingGroupArn;
                try {
                  const result = await iot.send(new CreateThingGroupCommand({ thingGroupName }));
                  thingGroupArn = result.thingGroupArn;
                } catch (err) {
                  if (!conflict(err)) throw err;
                  thingGroupArn = `arn:aws:iot:${region}:${accountId}:thinggroup/${thingGroupName}`;
                }

                try {
                  await iot.send(new AddThingToThingGroupCommand({ thingName, thingGroupName }));
                } catch (err) {
                  if (!conflict(err)) throw err;
                }

                try {
                  await iot.send(new CreatePolicyCommand({
                    policyName,
                    policyDocument: JSON.stringify(policyDoc(region, accountId, thingName))
                  }));
                } catch (err) {
                  if (!conflict(err)) throw err;
                }

                await iot.send(new AttachPolicyCommand({ policyName, target: thingGroupArn }));

                responseData = { PolicyName: policyName, ThingName: thingName };
              } else if (event.RequestType === 'Delete') {
                const thingGroupArn = `arn:aws:iot:${region}:${accountId}:thinggroup/${thingGroupName}`;
                try {
                  await iot.send(new DetachPolicyCommand({ policyName, target: thingGroupArn }));
                } catch (err) { if (!notFound(err)) throw err; }
                try {
                  await iot.send(new RemoveThingFromThingGroupCommand({ thingName, thingGroupName }));
                } catch (err) { if (!notFound(err)) throw err; }
                try {
                  await iot.send(new DeleteThingGroupCommand({ thingGroupName }));
                } catch (err) { if (!notFound(err)) throw err; }
                try {
                  await iot.send(new DeletePolicyCommand({ policyName }));
                } catch (err) { if (!notFound(err)) throw err; }
                try {
                  await iot.send(new DeleteThingCommand({ thingName }));
                } catch (err) { if (!notFound(err)) throw err; }
                responseData = {};
              }
            } catch (err) {
              console.error('Onboarding error:', JSON.stringify({ name: err.name, message: err.message, stack: err.stack }, null, 2));
              status = 'FAILED';
              responseData = { Error: `${err.name}: ${err.message}` };
            }
            await response.send(event, context, status, responseData, physicalId);
          };

  DeviceOnboardingCustomResource:
    Type: AWS::CloudFormation::CustomResource
    Properties:
      ServiceToken: !GetAtt OnboardingLambda.Arn
      ThingName: !Sub device-${AWS::StackName}
      PolicyName: !Sub device-onboarding-policy-${AWS::StackName}

Outputs:
  IotPolicyName:
    Description: Name of the generated IoT policy
    Value: !GetAtt DeviceOnboardingCustomResource.PolicyName

AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Bookstore Amazon Verified Permissions stack. Creates a Cedar policy store with
  STRICT schema validation and an inline Bookstore namespace Cedar schema (Role,
  User, Book entities; View and ViewWithPremiumOffers actions with a region
  context), seven static Cedar policies, and publishes the policy store ID to SSM.

Resources:

  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      Description: Bookstore Cedar policy store implementing Cedar-based access control for the bookstore application
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {},
                "User": {
                  "memberOfTypes": ["Role"],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long",
                        "required": true
                      }
                    }
                  }
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "Bookstore::User",
                        "required": true
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": ["User"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": ["User"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                }
              }
            }
          }

  AdminCanViewAnyBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit members of the Admin role to view any Book
          Statement: |-
            permit(
              principal in Bookstore::Role::"Admin",
              action == Bookstore::Action::"View",
              resource
            );

  BlockedAdminCannotViewPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid the specific named administrator user blocked-admin from viewing any Book; forbid takes precedence over permit
          Statement: |-
            forbid(
              principal == Bookstore::User::"blocked-admin",
              action == Bookstore::Action::"View",
              resource
            );

  PublisherCanViewOwnedBooksPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit members of the Publisher role to view only Books they themselves own
          Statement: |-
            permit(
              principal in Bookstore::Role::"Publisher",
              action == Bookstore::Action::"View",
              resource
            )
            when { resource.owner == principal };

  AliceCanViewBook42Policy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit the specific named user alice to view only the specific named Book book-42
          Statement: |-
            permit(
              principal == Bookstore::User::"alice",
              action == Bookstore::Action::"View",
              resource == Bookstore::Book::"book-42"
            );

  VeteranCustomerPremiumOffersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit members of the Customer role to view premium offers only once they have been members for two years or more
          Statement: |-
            permit(
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when { principal.yearsAsMember >= 2 };

  NewCustomerPremiumOffersForbiddenPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid Customer-role members with fewer than two years of membership from viewing premium offers, as defense in depth
          Statement: |-
            forbid(
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when { principal.yearsAsMember < 2 };

  NonUsRegionGuardPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Forbid all principals from View and ViewWithPremiumOffers whenever the request context region is not US (United States)
          Statement: |-
            forbid(
              principal,
              action in [Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers"],
              resource
            )
            when { context.region != "US" };

  BookstorePolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: /bookstore/verified-permissions/policy-store-id
      Type: String
      Value: !Ref BookstorePolicyStore
      Description: Amazon Verified Permissions policy store ID for the bookstore application Cedar authorization

Outputs:

  PolicyStoreId:
    Description: ID of the Bookstore Amazon Verified Permissions policy store
    Value: !Ref BookstorePolicyStore

  PolicyStoreIdParameterName:
    Description: Name of the SSM Parameter holding the Bookstore policy store ID
    Value: !Ref BookstorePolicyStoreIdParameter

AWSTemplateFormatVersion: '2010-09-09'
Description: >
  Step Functions calculator demo. An API-free state machine named Calculator-StateMachine
  routes input to a Node.js Lambda named Calculator that performs add, subtract,
  multiply, or divide. Unknown operators terminate the execution in a Fail state.
  All resources are self-contained; no external infrastructure is referenced.

Resources:
  CalculatorLambdaRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: 'sts:AssumeRole'
      Policies:
        - PolicyName: CalculatorLambdaLoggingPolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - 'logs:CreateLogGroup'
                  - 'logs:CreateLogStream'
                  - 'logs:PutLogEvents'
                Resource: !Sub 'arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:log-group:/aws/lambda/Calculator:*'

  CalculatorLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: /aws/lambda/Calculator
      RetentionInDays: 3

  CalculatorFunction:
    Type: AWS::Lambda::Function
    DependsOn: CalculatorLogGroup
    Properties:
      FunctionName: Calculator
      Runtime: nodejs24.x
      Handler: index.handler
      Architectures:
        - x86_64
      MemorySize: 128
      Timeout: 10
      Role: !GetAtt CalculatorLambdaRole.Arn
      Code:
        ZipFile: |
          exports.handler = async (event) => {
            const operator = event.operator;
            const operands = event.operands;

            if (!Array.isArray(operands) || operands.length < 2) {
              throw new Error('operands must be an array containing at least two numbers');
            }

            let result;
            switch (operator) {
              case 'add':
                result = operands.reduce((acc, value) => acc + value, 0);
                break;
              case 'subtract':
                result = operands.slice(1).reduce((acc, value) => acc - value, operands[0]);
                break;
              case 'multiply':
                result = operands.reduce((acc, value) => acc * value, 1);
                break;
              case 'divide':
                if (operands.slice(1).some((value) => value === 0)) {
                  throw new Error('Division by zero is not allowed');
                }
                result = operands.slice(1).reduce((acc, value) => acc / value, operands[0]);
                break;
              default:
                throw new Error('Unsupported operator: ' + operator);
            }

            return {
              operator: operator,
              operands: operands,
              result: result
            };
          };

  CalculatorStateMachineRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: states.amazonaws.com
            Action: 'sts:AssumeRole'
      Policies:
        - PolicyName: CalculatorStateMachineInvokePolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action: 'lambda:InvokeFunction'
                Resource: !Sub '${CalculatorFunction.Arn}'

  CalculatorStateMachine:
    Type: AWS::StepFunctions::StateMachine
    Properties:
      StateMachineName: Calculator-StateMachine
      RoleArn: !GetAtt CalculatorStateMachineRole.Arn
      DefinitionString: !Sub |
        {
          "Comment": "Calculator demo: routes on the operator field and invokes the Calculator Lambda",
          "StartAt": "RouteOperation",
          "States": {
            "RouteOperation": {
              "Type": "Choice",
              "Comment": "Branch on $.operator to the matching operation task",
              "Choices": [
                {
                  "Variable": "$.operator",
                  "StringEquals": "add",
                  "Next": "PerformAdd"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "subtract",
                  "Next": "PerformSubtract"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "multiply",
                  "Next": "PerformMultiply"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "divide",
                  "Next": "PerformDivide"
                }
              ],
              "Default": "UnsupportedOperator"
            },
            "PerformAdd": {
              "Type": "Task",
              "Resource": "${CalculatorFunction.Arn}",
              "Parameters": {
                "operator.$": "$.operator",
                "operands.$": "$.operands"
              },
              "TimeoutSeconds": 60,
              "End": true
            },
            "PerformSubtract": {
              "Type": "Task",
              "Resource": "${CalculatorFunction.Arn}",
              "Parameters": {
                "operator.$": "$.operator",
                "operands.$": "$.operands"
              },
              "TimeoutSeconds": 60,
              "End": true
            },
            "PerformMultiply": {
              "Type": "Task",
              "Resource": "${CalculatorFunction.Arn}",
              "Parameters": {
                "operator.$": "$.operator",
                "operands.$": "$.operands"
              },
              "TimeoutSeconds": 60,
              "End": true
            },
            "PerformDivide": {
              "Type": "Task",
              "Resource": "${CalculatorFunction.Arn}",
              "Parameters": {
                "operator.$": "$.operator",
                "operands.$": "$.operands"
              },
              "TimeoutSeconds": 60,
              "End": true
            },
            "UnsupportedOperator": {
              "Type": "Fail",
              "Error": "UnsupportedOperator",
              "Cause": "The input operator is not supported. Supported operators are: add, subtract, multiply, divide."
            }
          }
        }

Outputs:
  SampleInput:
    Description: Sample input format for the Calculator state machine execution
    Value: '{"operator": "add", "operands": [1, 2]}'
  StateMachineArn:
    Description: ARN of the Calculator-StateMachine state machine
    Value: !Ref CalculatorStateMachine
  LambdaFunctionArn:
    Description: ARN of the Calculator Lambda function
    Value: !GetAtt CalculatorFunction.Arn

AWSTemplateFormatVersion: "2010-09-09"
Description: Simple to-do GraphQL API on AWS AppSync backed by DynamoDB with JavaScript resolvers

Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      TableName: !Sub "${AWS::StackName}-todos"
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL

  AppSyncServiceRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncDynamoDBAccess
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub "${TodoTable.Arn}/index/owner-index"

  SimpleTodoAPI:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY

  SimpleTodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId

  TodoSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Definition: |
        type Todo {
          id: ID!
          title: String!
          content: String
          owner: String!
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        input CreateTodoInput {
          title: String!
          content: String
          owner: String!
        }

        input UpdateTodoInput {
          id: ID!
          title: String
          content: String
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          todosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

        type Subscription {
          onCreateTodo: Todo
            @aws_subscribe(mutations: ["createTodo"])
          onUpdateTodo: Todo
            @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo: Todo
            @aws_subscribe(mutations: ["deleteTodo"])
        }

  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Name: TodoTableDataSource
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncServiceRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { input } = ctx.args;
          const now = util.time.nowISO8601();
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: util.autoId() }),
            attributeValues: util.dynamodb.toMapValues({
              title: input.title,
              content: input.content,
              owner: input.owner,
              createdAt: now,
              updatedAt: now,
            }),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { id, title, content } = ctx.args.input;
          const expNames = {};
          const expValues = {};
          const expSet = [];

          if (title !== undefined) {
            expNames['#title'] = 'title';
            expValues[':title'] = util.dynamodb.toDynamoDB(title);
            expSet.push('#title = :title');
          }
          if (content !== undefined) {
            expNames['#content'] = 'content';
            expValues[':content'] = util.dynamodb.toDynamoDB(content);
            expSet.push('#content = :content');
          }
          expNames['#updatedAt'] = 'updatedAt';
          expValues[':updatedAt'] = util.dynamodb.toDynamoDB(util.time.nowISO8601());
          expSet.push('#updatedAt = :updatedAt');

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id }),
            update: {
              expression: `SET ${expSet.join(', ')}`,
              expressionNames: expNames,
              expressionValues: expValues,
            },
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: getTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: listTodos
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { limit, nextToken } = ctx.args;
          return {
            operation: 'Scan',
            limit: limit ?? undefined,
            nextToken: nextToken ?? undefined,
          };
        }

        export function response(ctx) {
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

  TodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: todosByOwner
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: "1.0.0"
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { owner, limit, nextToken } = ctx.args;
          return {
            operation: 'Query',
            index: 'owner-index',
            query: {
              expression: 'owner = :owner',
              expressionValues: {
                ':owner': util.dynamodb.toDynamoDB(owner),
              },
            },
            limit: limit ?? undefined,
            nextToken: nextToken ?? undefined,
          };
        }

        export function response(ctx) {
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

Outputs:
  GraphQLApiUrl:
    Description: GraphQL endpoint URL
    Value: !GetAtt SimpleTodoAPI.GraphQLUrl
  GraphQLApiId:
    Description: AppSync API ID
    Value: !GetAtt SimpleTodoAPI.ApiId
  TodoTableName:
    Description: DynamoDB table name
    Value: !Ref TodoTable
